// generated by scripts/gen_types.py — do not edit
// Run `backend/.venv/bin/python scripts/gen_types.py` after changing the API models.

// What the server sends: State over /api/ws and /api/status (GET /api/schema/state).

export interface State {
  instance_id: string;
  revision: number;
  run_id: string;
  status: 'initializing' | 'paused' | 'running' | 'error' | 'stopped';
  error: string | null;
  config: RunConfig;
  interventions: Interventions;
  sample: Sample | null;
  history: Sample[];
  trail: number[][];
  events: Event[];
  wall_s: number;
  real_time_factor: number;
  compute_real_time_factor: number;
  memory_mb: number;
  frame_revision: number;
  rendering: boolean;
  render_error: string | null;
  subscribers: number;
  recording_samples: number;
  recording_limit: number;
  provenance: Provenance | null;
  metrics: RunMetrics;
  vision: Vision;
  batch: Batch | null;
  connectome: ConnectomeLive | null;
}

/** The active or last comparison. */
export interface Batch {
  id: string;
  status: 'running' | 'paused' | 'completed' | 'cancelled' | 'failed';
  total: number;
  current: number;
  results: BatchTrial[];
  protocol: string;
  cell_type: string | null;
  max_speed: boolean;
  condition?: string;
  seed?: number;
  error?: string;
  partial?: BatchTrial;
  partial_error?: string;
  restore_error?: string;
}

/** A saved comparison trial: where its export is and its metrics. */
export interface BatchTrial {
  batch_id: string;
  condition: string;
  seed: number;
  index: number;
  total: number;
  neural_model?: 'engineered' | 'connectome';
  cell_type: string | null;
  partial?: boolean;
  run_id: string;
  samples: number;
  path: string;
  download_url: string;
  metrics: RunMetrics;
}

/**
 * FlyGym body measurements of one sample; the toy body has none. Display history leaves out joint angles.
 */
export interface BodySignals {
  leg_order?: string[];
  ground_contact_force?: number[];
  contact?: boolean[];
  contact_threshold?: number;
  cpg_phase_rad?: number[];
  joint_position_rad?: number[];
  force_unit?: string;
  source?: string;
}

/**
 * An engineered manipulation of one cell type's neurons on one side or both (connectome model only):
 * silence: no output (value ignored); scale: output × value (0–2); activate: independent Poisson input at value Hz
 * to each neuron (spiking dynamics, above 0 up to 500) or its rate clamped to value (rate dynamics, above 0 up to 1).
 * Equations: docs/ARCHITECTURE.md, "Connectome interventions".
 */
export interface CellTypeIntervention {
  name: string;
  side: 'both' | 'left' | 'right';
  mode: 'silence' | 'scale' | 'activate';
  value: number;
}

/** Display-only activity of the connectome model, at the publish rate; not recorded. */
export interface ConnectomeLive {
  circuit: string;
  circuit_sha256: string;
  dynamics: 'rate' | 'spiking';
  unit_names: string[];
  readout_types: string[];
  type_rates: number[];
  turn: number;
  motor_clipped_fraction: number;
  silenced_neurons: number;
  manipulated_neurons: ManipulatedNeurons;
  trace_t: number[];
  top_types: TypeTrace[];
}

/**
 * Settings of the connectome model. All are global: nothing addresses a single neuron or synapse.
 */
export interface ConnectomeParameters {
  circuit: string;
  dynamics: 'rate' | 'spiking';
  synapse_threshold: number;
  global_gain: number;
  input_gain: number;
  output_gain: number;
  tonic_drive: number;
  tau_ms: number;
  other_transmitters: 'excluded' | 'excitatory';
  readout_types: string[] | null;
  input_types: string[] | null;
  speed_types: string[];
  speed_gain: number;
  spiking: SpikingParameters;
  readout_weights: Record<string, number> | null;
  readout_pool: 'sum' | 'mean';
  motor_delay_ms: number;
  motor_tau_ms: number;
}

export interface Event {
  seq: number;
  step: number;
  t: number;
  kind: string;
  message: string;
  payload: Record<string, unknown>;
}

export interface Interventions {
  zero_left: boolean;
  zero_right: boolean;
  silence: 'none' | 'sensory' | 'steering' | 'descending' | 'all';
  silence_dna02: 'none' | 'left' | 'right' | 'both';
  silence_types: string[];
  cell_types: CellTypeIntervention[];
}

/** Neurons each intervention mode reaches now. */
export interface ManipulatedNeurons {
  silence: number;
  scale: number;
  activate: number;
}

export interface NeuralParameters {
  sensory_gain: number;
  steering_gain: number;
  tonic_drive: number;
  time_scale: number;
}

export interface Pose {
  x: number;
  y: number;
  z: number;
  yaw: number;
  velocity: number;
  legs: number[][][];
}

export interface Protocol {
  name: string;
  duration_steps: number;
  events: ProtocolEvent[];
}

export interface ProtocolEvent {
  step: number;
  stimulus: Stimulus | null;
  interventions: Interventions | null;
}

/**
 * Plain-language labels of what produced the run: which parts are data-derived, published or engineered.
 */
export interface Provenance {
  body_engine: string;
  sensor_model: string;
  neural_model: string;
  motor_controller: string;
  connectivity_source: string;
  input_mapping: string;
  controller_mode: string;
  viewport: string;
  body_sex: string;
  anatomy_atlas: string;
}

export interface RunConfig {
  engine: 'flygym' | 'toy';
  seed: number;
  controller: 'neural' | 'baseline';
  speed: number;
  stimulus: Stimulus;
  sensor_model: 'geometric' | 'vision' | 'flyvis';
  neural_model: 'engineered' | 'connectome';
  neural_parameters: NeuralParameters;
  connectome_parameters: ConnectomeParameters;
  initial_interventions: Interventions;
  protocol: Protocol | null;
  record_activity: 'none' | 'types';
}

/**
 * Behaviour since the reset; empty before the run's first sample, and in older saved runs some are missing.
 */
export interface RunMetrics {
  path_length_mm?: number;
  displacement_mm?: number;
  mean_speed_mm_s?: number;
  net_turn_deg?: number;
  target_distance_mm?: number;
  min_target_distance_mm?: number;
  contact_fraction?: number[];
  duration_s?: number;
  protocol_complete?: boolean;
}

export interface Sample {
  step: number;
  t: number;
  pose: Pose;
  sensors: SensorState;
  rates: number[];
  motor: number[];
  body_signals: BodySignals;
}

export interface SensorState {
  left: number;
  right: number;
  raw_left: number;
  raw_right: number;
  bearing_rad: number;
  distance_mm: number;
}

/**
 * Shiu et al. 2024's one free parameter plus the closed-loop input and readout. Neuron constants are fixed.
 */
export interface SpikingParameters {
  synapse_weight_mv: number;
  input_rate_hz: number;
  rate_window_ms: number;
  rate_scale_hz: number;
}

export interface Stimulus {
  x: number;
  y: number;
  intensity: number;
}

export interface TypeTrace {
  index: number;
  name: string;
  trace: number[];
}

/** The latest eye reading, with compound-eye or FlyVis sensing; empty otherwise. */
export interface Vision {
  ommatidia_per_eye?: number;
  left?: number[];
  right?: number[];
  sample_interval_s?: number;
  sample_time_s?: number;
  encoder?: string;
}

// Request bodies and documented responses (/api/openapi.json).

export interface BatchRequest {
  config: RunConfigInput;
  seeds?: number[];
  conditions?: (
    | 'control'
    | 'left_sensor_off'
    | 'descending_off'
    | 'baseline'
    | 'engineered_model'
    | 'connectome_model'
    | 'dna02_left_off'
    | 'dna02_right_off'
    | 'dna02_both_off'
    | 'cell_type_off'
  )[];
  cell_type?: string | null;
  custom_conditions?: CustomCondition[];
  max_speed?: boolean;
}

export interface BatchSummary {
  batch_id: string;
  n_trials: number;
  partial_trials: number;
  duplicate_trials: number;
  reach_mm: number;
  conditions: ConditionSummary[];
  paired: PairedDifference[];
  methods: Record<string, string>;
}

export interface BuildRequest {
  name: string;
  seeds: string[];
  hops?: number;
  threshold?: number;
  cap?: number;
  whole_brain?: boolean;
  balance_sides?: boolean;
}

/**
 * An engineered manipulation of one cell type's neurons on one side or both (connectome model only):
 * silence: no output (value ignored); scale: output × value (0–2); activate: independent Poisson input at value Hz
 * to each neuron (spiking dynamics, above 0 up to 500) or its rate clamped to value (rate dynamics, above 0 up to 1).
 * Equations: docs/ARCHITECTURE.md, "Connectome interventions".
 */
export interface CellTypeInterventionInput {
  name: string;
  side?: 'both' | 'left' | 'right';
  mode: 'silence' | 'scale' | 'activate';
  value?: number;
}

export interface ConditionSummary {
  condition: string;
  n: number;
  metrics: Record<string, MetricSummary>;
}

export interface ConnectivityGraph {
  provenance: GraphSource;
  nodes: GraphNode[];
  edges: GraphEdge[];
}

/**
 * Settings of the connectome model. All are global: nothing addresses a single neuron or synapse.
 */
export interface ConnectomeParametersInput {
  circuit?: string;
  dynamics?: 'rate' | 'spiking';
  synapse_threshold?: number;
  global_gain?: number;
  input_gain?: number;
  output_gain?: number;
  tonic_drive?: number;
  tau_ms?: number;
  other_transmitters?: 'excluded' | 'excitatory';
  readout_types?: string[] | null;
  input_types?: string[] | null;
  speed_types?: string[];
  speed_gain?: number;
  spiking?: SpikingParametersInput;
  readout_weights?: Record<string, number> | null;
  readout_pool?: 'sum' | 'mean';
  motor_delay_ms?: number;
  motor_tau_ms?: number;
}

/**
 * A comparison condition of your own: its trials hold `interventions` (none when null) and, with the connectome
 * model, the configuration's connectome parameters with these live-editable fields changed (a partial `spiking`
 * keeps the other spiking settings).
 */
export interface CustomCondition {
  label: string;
  interventions?: InterventionsInput | null;
  connectome_parameters?: Record<string, unknown> | null;
}

export interface ExportRequest {
  share_safe?: boolean;
}

export interface GraphEdge {
  pre_id: string;
  post_id: string;
  synapse_count: number;
}

export interface GraphNode {
  id: string;
  label: string;
  cell_type?: string;
  side?: 'left' | 'right' | 'midline' | 'unknown';
}

export interface GraphSource {
  kind: 'biological' | 'synthetic';
  dataset: string;
  release: string;
  specimen: string;
  sex: 'female' | 'male' | 'unknown' | 'mixed';
  source_url: string;
  license: string;
  coverage: string;
  weight_assumption: string;
}

export interface InterventionsInput {
  zero_left?: boolean;
  zero_right?: boolean;
  silence?: 'none' | 'sensory' | 'steering' | 'descending' | 'all';
  silence_dna02?: 'none' | 'left' | 'right' | 'both';
  silence_types?: string[];
  cell_types?: CellTypeInterventionInput[];
}

export interface MethodsText {
  markdown: string;
}

export interface MetricSummary {
  mean: number | null;
  sd: number | null;
  ci95: [number, number] | null;
}

export interface NeuralParametersInput {
  sensory_gain?: number;
  steering_gain?: number;
  tonic_drive?: number;
  time_scale?: number;
}

export interface PairedDifference {
  condition: string;
  baseline: string;
  metric: string;
  mean_diff: number | null;
  ci95: [number, number] | null;
  n_pairs: number;
}

export interface PresetRequest {
  name: string;
  description?: string;
  config: RunConfigInput;
}

export interface ProtocolEventInput {
  step: number;
  stimulus?: StimulusInput | null;
  interventions?: InterventionsInput | null;
}

export interface ProtocolInput {
  name?: string;
  duration_steps?: number;
  events?: ProtocolEventInput[];
}

/** The latest replay check of a saved run (its replay.json, from scripts/replay.py --save). */
export interface ReplayVerdict {
  ok: boolean;
  max_abs_error: number;
  tolerance: number;
  checked: string;
  same_software: boolean;
  message: string;
  samples_compared?: number;
  column_errors?: Record<string, number | null>;
  software_differences?: string[];
}

/**
 * A researcher's tags and notes on a saved run, kept in its annotations.json; metadata.json never changes.
 * As a PATCH body, only the fields given are changed.
 */
export interface RunAnnotations {
  tags?: string[];
  notes?: string;
}

export interface RunConfigInput {
  engine?: 'flygym' | 'toy';
  seed?: number;
  controller?: 'neural' | 'baseline';
  speed?: number;
  stimulus?: StimulusInput;
  sensor_model?: 'geometric' | 'vision' | 'flyvis';
  neural_model?: 'engineered' | 'connectome';
  neural_parameters?: NeuralParametersInput;
  connectome_parameters?: ConnectomeParametersInput;
  initial_interventions?: InterventionsInput;
  protocol?: ProtocolInput | null;
  record_activity?: 'none' | 'types';
}

/** A saved run in the library. Older runs may lack configuration fields and metrics added since. */
export interface RunItem {
  key: string;
  run_id: string;
  created_utc: string;
  config: RunConfigInput;
  samples: number;
  metrics: RunMetrics;
  trial: TrialRecord | null;
  error: string | null;
  provenance: Record<string, string>;
  download_url: string;
  batch_id: string | null;
  condition: string | null;
  tags: string[];
  notes: string;
  verified: ReplayVerdict | null;
}

export interface RunPage {
  runs: RunItem[];
}

export interface Shutdown {
  instance_id: string;
}

export interface Speed {
  speed: number;
}

/**
 * Shiu et al. 2024's one free parameter plus the closed-loop input and readout. Neuron constants are fixed.
 */
export interface SpikingParametersInput {
  synapse_weight_mv?: number;
  input_rate_hz?: number;
  rate_window_ms?: number;
  rate_scale_hz?: number;
}

export interface StimulusInput {
  x?: number;
  y?: number;
  intensity?: number;
}

export type StrictModel = Record<string, never>;

/** A comparison trial, as saved in its run's metadata.trial. */
export interface TrialRecord {
  batch_id: string;
  condition: string;
  seed: number;
  index: number;
  total: number;
  neural_model?: 'engineered' | 'connectome';
  cell_type?: string | null;
  partial?: boolean;
}

/** The JSON body each command takes. */
export interface RequestBodies {
  'POST /api/batch/cancel': StrictModel;
  'POST /api/batch/start': BatchRequest;
  'POST /api/configs': PresetRequest;
  'POST /api/connectivity/import': ConnectivityGraph;
  'POST /api/connectome/build': BuildRequest;
  'POST /api/connectome/parameters': ConnectomeParametersInput;
  'POST /api/export': ExportRequest;
  'POST /api/interventions': InterventionsInput;
  'POST /api/jobs/{job_id}/cancel': StrictModel;
  'POST /api/parameters': NeuralParametersInput;
  'POST /api/pause': StrictModel;
  'POST /api/reset': RunConfigInput;
  'POST /api/run': StrictModel;
  'PATCH /api/runs/{key}': RunAnnotations;
  'POST /api/runs/{key}/replay': StrictModel;
  'POST /api/shutdown': Shutdown;
  'POST /api/speed': Speed;
  'POST /api/step': StrictModel;
  'POST /api/stimulus': StimulusInput;
}

/** Responses with a documented shape. */
export interface Responses {
  'GET /api/batches/{batch_id}/methods': MethodsText;
  'GET /api/batches/{batch_id}/summary': BatchSummary;
  'GET /api/runs': RunPage;
  'PATCH /api/runs/{key}': RunItem;
  'GET /api/runs/{key}/methods': MethodsText;
}
